import math

import pytest

from retention_py import compute_retention as compute_py
from retention_sql import compute_retention as compute_sql


@pytest.fixture(scope="module")
def sql_result():
    return compute_sql()


@pytest.fixture(scope="module")
def py_result():
    return compute_py()


def test_same_cell_keys(sql_result, py_result):
    assert set(sql_result) == set(py_result)
    # 31 daily cohorts fall into exactly 5 ISO weeks x 8 lags
    cohort_weeks = {w for w, _ in sql_result}
    assert len(cohort_weeks) == 5
    assert all(k == int(k) for _, k in sql_result)


def test_identical_to_six_decimals(sql_result, py_result):
    for cell in sorted(sql_result):
        assert math.isclose(sql_result[cell], py_result[cell],
                            abs_tol=1e-6), f"mismatch at {cell}"


def test_retention_never_exceeds_one(sql_result):
    for cell, value in sql_result.items():
        assert value <= 1.0, f"retention {value} > 1.0 at {cell}"
        assert value >= 0.0


def test_week1_average_near_design_rate(sql_result):
    week1 = [v for (_, k), v in sql_result.items() if k == 1]
    avg = sum(week1) / len(week1)
    assert abs(avg - 0.44) <= 0.05, f"week-1 average {avg} outside 0.44 +/- 0.05"
